										{
											input.Display_Name_Customer = "";
										}

if(input.Discount_Amount == null)
										{
											input.Discount_Amount = 0;
										}
										if(input.Discount_Amount > ifnull(input.Sub_Total,0))
										{
											alert "Discount Amount cannot be greater than Sub Total.";
											input.Discount_Amount = ifnull(input.Sub_Total,0);
										}
										input.Grand_Total = ifnull(input.Sub_Total,0) + ifnull(input.Tax_Amount,0) - ifnull(input.Discount_Amount,0);
										input.Balance_Due = ifnull(input.Grand_Total,0) - ifnull(input.Amount_Paid,0);

if(input.Discount_Percentage == null)
										{
											input.Discount_Percentage = 0;
										}
										if(input.Discount_Percentage > 100)
										{
											alert "Discount Percentage cannot be greater than 100%.";
											input.Discount_Percentage = 100;
										}
										discount_amt = ifnull(input.Sub_Total,0) * ifnull(input.Discount_Percentage,0) / 100;
										input.Discount_Amount = discount_amt;
										input.Grand_Total = ifnull(input.Sub_Total,0) + ifnull(input.Tax_Amount,0) - discount_amt;
										input.Balance_Due = ifnull(input.Grand_Total,0) - ifnull(input.Amount_Paid,0);

if(input.Discount_Type == "None")
										{
											hide Discount_Percentage;
											hide Discount_Amount;
											input.Discount_Percentage = 0;
											input.Discount_Amount = 0;
										}
										else if(input.Discount_Type == "Percentage")
										{
											show Discount_Percentage;
											hide Discount_Amount;
											input.Discount_Amount = 0;
										}
										else if(input.Discount_Type == "Amount")
										{
											hide Discount_Percentage;
											show Discount_Amount;
											input.Discount_Percentage = 0;
										}

if(input.Send_Invoice == true)
										{
											show Fiscal_Document_Number;
											show Date_Sent;
										}
										else
										{
											hide Fiscal_Document_Number;
											hide Date_Sent;
											input.Fiscal_Document_Number = "";
											input.Date_Sent = null;
										}

if(row.Service != null)
										{
											row.Display_Name_Service=row.Service.Service_Name;
										}
										else
										{
											row.Display_Name_Service="";
										}

sub_total = ifnull(input.Sub_Total,0.0);
										discount = ifnull(input.Discount_Amount,0.0);
										grand_total = sub_total - discount + ifnull(input.Tax_Amount,0.0);
										input.Grand_Total = grand_total;
										input.Balance_Due = grand_total - ifnull(input.Amount_Paid,0.0);

if(input.Company == null)
										{
											alert "Company is required.";
											cancel submit;
										}
										if(input.Invoice_Date == null)
										{
											alert "Invoice Date is required.";
											cancel submit;
										}
										if(input.Invoice_Number == null || input.Invoice_Number.trim() == "")
										{
											alert "Invoice Number is required.";
											cancel submit;
										}
										if(input.Customer == null)
										{
											alert "Customer is required.";
											cancel submit;
										}
										if(input.Send_Invoice == true && input.Cancel_Invoice == true)
										{
											alert "An Invoice cannot be Sent and Cancelled at the same time.";
											cancel submit;
										}
										if(input.Send_Invoice == true && input.Fiscal_Document_Number == null || input.Fiscal_Document_Number.trim() == "")
										{
											alert "FD Number is required When Sending an Invoice.";
											cancel submit;
										}
										if(input.Cancel_Invoice == true && input.Reason_Why_Cancelled == null || input.Reason_Why_Cancelled.trim() == "")
										{
											alert "Reason Why Cancelled is required When Cancelling an Invoice.";
											cancel submit;
										}

if(input.Cancel_Invoice == true)
										{
											input.Invoice_Status = "Cancelled";
										}
										else if(input.Send_Invoice == true)
										{
											input.Invoice_Status = "Invoiced";
											if(input.Date_Sent == null)
											{
												input.Date_Sent = zoho.currentdate;
											}
										}
										else
										{
											input.Invoice_Status = "Draft";
										}
										// ==============================
										// INVOICE FINALIZE TOTALS
										// ==============================
										sub_total = 0.0;
										for each  d in Invoice_Details[Invoice == input.ID]
										{
											sub_total = sub_total + ifnull(d.Line_Total,0.0);
										}
										for each  s in input.Services
										{
											if(input.Invoice_Number != null && input.Invoice_Number != "")
											{
												s.Display_Name_Voucher=input.Invoice_Number;
											}
											sub_total = sub_total + ifnull(s.Line_Total,0.0);
										}
										input.Sub_Total = sub_total;
										discount_amt = ifnull(input.Discount_Amount,0.0);
										if(input.Discount_Type == "Percentage")
										{
											discount_amt = sub_total * ifnull(input.Discount_Percentage,0.0) / 100;
											input.Discount_Amount = discount_amt;
										}
										grand_total = sub_total - discount_amt + ifnull(input.Tax_Amount,0.0);
										if(grand_total < 0)
										{
											grand_total = 0;
										}
										input.Grand_Total = grand_total;
										balance_due = grand_total - ifnull(input.Amount_Paid,0.0);
										if(balance_due < 0)
										{
											balance_due = 0;
										}
										input.Balance_Due = balance_due;

if(input.Sales_Voucher_Date == null)
										{
											input.Sales_Voucher_Date = zoho.currentdate;
										}
										for each  row in input.Product_Details
										{
											row.Display_Name_Sales_Voucher=input.Sales_Voucher_Number;
										}

// =====================================================
