u = thisapp.audit.getLoginAuditInfo();
										input.Created_By_Name = u.get("name");
										input.Created_By_Email = u.get("email");
										input.Created_By_Time = zoho.currenttime;

u = thisapp.audit.getLoginAuditInfo();
										input.Updated_By_Name = u.get("name");
										input.Updated_By_Email = u.get("email");
										input.Updated_By_Time = zoho.currenttime;

if(input.Bill_Type == "Store Bill")
										{
											show Vendor;
											hide Employee_Vendor;
											hide Sales_Voucher;
											hide Customer;
											hide Invoice;
											hide Display_Name_Vendor;
											input.Employee_Vendor = null;
											input.Sales_Voucher = null;
											input.Customer = null;
											input.Invoice = null;
											input.Display_Name_Vendor = "";
										}
										else if(input.Bill_Type == "Employee Bill")
										{
											hide Vendor;
											show Employee_Vendor;
											hide Sales_Voucher;
											hide Customer;
											hide Invoice;
											hide Display_Name_Vendor;
											input.Vendor = null;
											input.Customer = null;
											input.Invoice = null;
											input.Sales_Voucher = null;
										}
										else if(input.Bill_Type == "Invoice Bill")
										{
											show Invoice;
											hide Employee_Vendor;
											show Vendor;
											hide Sales_Voucher;
											hide Display_Name_Vendor;
											input.Vendor = null;
											input.Employee_Vendor = null;
											input.Display_Name_Vendor = "";
