											show Customer;
											hide Employee_Vendor;
											hide Vendor;
											hide Invoice;
											show Sales_Voucher;
											hide Display_Name_Vendor;
											input.Vendor = null;
											input.Invoice = null;
											input.Employee_Vendor = null;
											input.Display_Name_Vendor = "";
										}
										else
										{
											hide Vendor;
