										{
											cust_rec = Customer_Register[ID == input.Customer];
											if(cust_rec.ID != null)
											{
												input.Display_Name_Vendor = ifnull(cust_rec.Customer_Name,"") + " - " + ifnull(cust_rec.Customer_Code,"");
											}
										}
										else
										{
											input.Display_Name_Vendor = "";
										}

if(input.Employee_Vendor != null)
										{
											input.Display_Name_Vendor = input.Employee_Vendor.Employee_Name + " - " + input.Employee_Vendor.Employee_Number.toString();
										}
										else
										{
											input.Display_Name_Vendor = "";
										}

if(input.Invoice != null)
										{
											input.Bill_Name = "Invoice";
											input.Bill_Number = input.Invoice.Invoice_Number;
											disable Bill_Name;
											disable Bill_Number;
											disable Display_Name_Vendor;
										}
										else
