											enable Bill_Number;
											enable Display_Name_Vendor;
										}

// =======================================
										// Bill - ON VALIDATE
										// =======================================
										if(input.Bill_Date == null)
										{
											alert "Bill Date is required.";
											cancel submit;
										}
										else if(input.Bill_Date > zoho.currentdate)
										{
											alert "Bill Date cannot be in the future.";
											cancel submit;
										}
										if(input.Bill_Type == "Store Bill")
										{
											if(input.Vendor == null)
											{
												alert "Vendor is required for Store Bill.";
												cancel submit;
											}
										}
										else if(input.Bill_Type == "Employee Bill")
										{
											if(input.Employee_Vendor == null)
											{
												alert "Employee Vendor is required for Employee Bill.";
												cancel submit;
											}
										}
										else if(input.Bill_Type == "Sales Voucher Bill")
										{
											if(input.Sales_Voucher == null)
											{
												alert "Sales Voucher is required for Sales Voucher Bill.";
												cancel submit;
											}
										}
										if(isnull(input.Bill_Name) || input.Bill_Name.trim() == "")
										{
											alert "Bill Name is required.";
											cancel submit;
										}
										if(isnull(input.Bill_Number) || input.Bill_Number.trim() == "")
										{
											alert "Bill Number is required.";
											cancel submit;
										}
