										// PREVENT DUPLICATE BILL ENTRY
										// ===============================
										if(input.Bill_Type == "Store Bill")
										{
											dup = Bill[Bill_Number == input.Bill_Number && Bill_Name == input.Bill_Name && Vendor == input.Vendor && Bill_Type == input.Bill_Type && ID != input.ID];
											if(dup.count() > 0)
											{
												alert "Duplicate Store Bill detected.";
												cancel submit;
											}
