										{
											input.Quantity_in_Base_Unit_Of_Measure_Received = null;
											input.Line_Total = null;
											return;
										}
										if(input.Receiving_Type == "Internal Transfer")
										{
											to_receive = ifnull(input.Quantity_to_Receive,0.0);
											if(input.Quantity_Received != to_receive)
											{
												alert "For Internal Transfer, Quantity Received must equal Quantity to Receive: " + to_receive;
												input.Quantity_in_Base_Unit_Of_Measure_Received = null;
												input.Line_Total = null;
												return;
											}
										}
										else if(input.Receiving_Type == "Stock Return" || input.Receiving_Type == "Tool Return")
										{
											to_receive = ifnull(input.Quantity_to_Receive,0.0);
											if(input.Quantity_Received > to_receive)
											{
												alert "You cannot return more than the remaining quantity. Remaining: " + to_receive;
												input.Quantity_in_Base_Unit_Of_Measure_Received = null;
												input.Line_Total = null;
												return;
