											{
												alert "You cannot receive more than the remaining quantity. Remaining: " + to_receive;
												input.Quantity_in_Base_Unit_Of_Measure_Received = null;
												input.Line_Total = null;
												return;
											}
										}
										item_id = null;
										if(input.Receiving_Type == "Purchase Order")
										{
											if(input.Item != null)
											{
												po_det = Purchase_Order_Details[ID == input.Item];
												if(po_det.ID != null && po_det.Item != null)
												{
													item_id = po_det.Item;
												}
											}
										}
										else if(input.Receiving_Type == "Internal Transfer")
										{
											if(input.Transfer_Item != null && input.Transfer_Item.Item != null)
											{
												item_id = input.Transfer_Item.Item;
											}
										}
										else if(input.Receiving_Type == "Stock Return" || input.Receiving_Type == "Tool Return")
										{
											if(input.Item_Issuing_Details != null)
											{
												issue_rec = Item_Issuing_Details[ID == input.Item_Issuing_Details];
												if(issue_rec.ID != null && issue_rec.Item != null)
												{
													item_id = issue_rec.Item;
