										check = store_management.po.check_uom_conversion_from_masaka_site_management(item_id,input.Unit_Of_Measure_Received);
										if(check == null)
										{
											alert "No response was returned while checking the UOM conversion.";
											input.Quantity_in_Base_Unit_Of_Measure_Received = null;
											input.Line_Total = null;
											return;
										}
										if(ifnull(check.get("ok"),false) != true)
										{
											error_message = "UOM conversion failed.";
											if(check.get("message") != null)
											{
												error_message = check.get("message").toString();
											}
											alert error_message;
											input.Quantity_in_Base_Unit_Of_Measure_Received = null;
											input.Line_Total = null;
											return;
										}
										resp = store_management.po.recalculate_po_detail_line_from_masaka_site_management(item_id,input.Unit_Of_Measure_Received,input.Quantity_Received,ifnull(input.Rate,0.0));
