										{
											alert "No response was returned while converting the quantity.";
											input.Quantity_in_Base_Unit_Of_Measure_Received = null;
											input.Line_Total = null;
											return;
										}
										base_qty = ifnull(resp.get("qty_in_base"),0.0);
										if(base_qty <= 0)
										{
											alert "Unable to calculate the quantity in base unit.";
											input.Quantity_in_Base_Unit_Of_Measure_Received = null;
											input.Line_Total = null;
											return;
										}
										input.Quantity_in_Base_Unit_Of_Measure_Received = base_qty.round(2);
										if(input.Rate != null && input.Rate >= 0)
										{
											input.Line_Total = (input.Quantity_Received * input.Rate).round(2);
										}
										else
										{
											input.Line_Total = null;
										}

if(input.Receiving_Type == "Internal Transfer")
