											{
												errors.add("• Purchase Order is required.");
											}
											else if(input.Item == null)
											{
												errors.add("• Purchase Order line Item is required.");
											}
											else
											{
												po_det = Purchase_Order_Details[ID == input.Item];
												if(po_det.ID == null || po_det.Item == null)
