											}
											if(rtype == "Internal Transfer")
											{
												existing_transfer = Stock_Receiving_Details[Receiving_Type == "Internal Transfer" && Transfer_Item == selected_issue_id && ID != input.ID];
												if(existing_transfer.count() > 0)
